places.forEach(p=>Object.assign(p,original[p.id]));
const add=(id,name,short,zone,type,source,fact,desc,actions)=>places.push({id,name,short,zone,type,source,fact,desc,icon:CAMPUS_ZONES.find(z=>z.id===zone).icon,actions});
